import { renderSqlTemplate, stripSqlFilterBlocks } from '@nao/shared/sql-template';
import { describe, expect, it } from 'vitest';

import { assertSafeSqlIdentifier } from '../src/services/story-filters';

describe('story filter SQL templates', () => {
	it('strips filter blocks for chat / live baseline execution', () => {
		const sql = `
SELECT SUM(revenue) AS revenue
FROM orders
WHERE 1 = 1
{% filter country %} AND country IN ({{ filters.country.sql }}) {% endfilter %}
`.trim();

		expect(stripSqlFilterBlocks(sql)).toContain('WHERE 1 = 1');
		expect(stripSqlFilterBlocks(sql)).not.toContain('{% filter');
		expect(stripSqlFilterBlocks(sql)).not.toContain('country IN');
	});

	it('renders active filter selections into executable SQL', () => {
		const sql = `
SELECT SUM(revenue) AS revenue
FROM orders
WHERE 1 = 1
{% filter country %} AND country IN ({{ filters.country.sql }}) {% endfilter %}
`.trim();

		expect(
			renderSqlTemplate(sql, { country: ['US', 'FR'] }, { country: 'multi_select' }),
		).toContain("AND country IN ('US', 'FR')");
	});
});

describe('assertSafeSqlIdentifier', () => {
	it('accepts dotted and quoted identifiers', () => {
		expect(assertSafeSqlIdentifier('orders', 'table')).toBe('orders');
		expect(assertSafeSqlIdentifier('public.orders', 'table')).toBe('public.orders');
		expect(assertSafeSqlIdentifier('"Order Status"', 'column')).toBe('"Order Status"');
	});

	it('rejects unsafe identifiers', () => {
		expect(() => assertSafeSqlIdentifier('orders; DROP TABLE x', 'table')).toThrow(/Invalid filter table/);
		expect(() => assertSafeSqlIdentifier('col-name', 'column')).toThrow(/Invalid filter column/);
	});
});

import { useCallback, useEffect, useMemo, useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import { isFilterSelectionActive, type StoryFilterSelection, type StoryFilterSelections } from '@nao/shared/sql-template';
import { getStoryFiltersFromCode, type ParsedFilterBlock } from '@nao/shared/story-segments';

import type { QueryDataMap } from '@/components/story-embeds';
import { useDebouncedValue } from '@/hooks/use-debounced-value';
import { trpc } from '@/main';

export type StoryFilterApi =
	| { kind: 'owned'; chatId: string; storySlug: string }
	| { kind: 'shared'; shareId: string };

const FILTER_PARAM_PREFIX = 'story_filter_';

export function useStoryFilters({
	code,
	baselineQueryData,
	api,
	enabled = true,
}: {
	code: string;
	baselineQueryData?: QueryDataMap | null;
	api?: StoryFilterApi | null;
	enabled?: boolean;
}) {
	const filters = useMemo(() => dedupeFilters(getStoryFiltersFromCode(code)), [code]);
	const [selections, setSelections] = useState<StoryFilterSelections>(() => readSelectionsFromUrl(filters));

	useEffect(() => {
		setSelections(readSelectionsFromUrl(filters));
	}, [filters]);

	useEffect(() => {
		writeSelectionsToUrl(selections, filters);
	}, [selections, filters]);

	const setSelection = useCallback((filterId: string, selection: StoryFilterSelection) => {
		setSelections((current) => {
			const next = { ...current };
			if (isEmptySelection(selection)) {
				delete next[filterId];
			} else {
				next[filterId] = selection;
			}
			return next;
		});
	}, []);

	const clearSelections = useCallback(() => setSelections({}), []);

	const activeSelections = useMemo(() => {
		const active: StoryFilterSelections = {};
		for (const filter of filters) {
			const selection = selections[filter.id];
			if (isFilterSelectionActive(filter.filterType, selection)) {
				active[filter.id] = selection;
			}
		}
		return active;
	}, [filters, selections]);

	const hasActiveFilters = Object.keys(activeSelections).length > 0;
	const debouncedSelections = useDebouncedValue(activeSelections, 300);
	const debouncedHasActive = Object.keys(debouncedSelections).length > 0;

	const ownedQuery = useQuery({
		...trpc.story.getFilteredQueryData.queryOptions({
			chatId: api?.kind === 'owned' ? api.chatId : '',
			storySlug: api?.kind === 'owned' ? api.storySlug : '',
			selections: debouncedSelections,
		}),
		enabled: Boolean(enabled && api?.kind === 'owned' && debouncedHasActive),
	});

	const sharedQuery = useQuery({
		...trpc.storyShare.getFilteredQueryData.queryOptions({
			shareId: api?.kind === 'shared' ? api.shareId : '',
			selections: debouncedSelections,
		}),
		enabled: Boolean(enabled && api?.kind === 'shared' && debouncedHasActive),
	});

	const filteredQueryData = (api?.kind === 'shared' ? sharedQuery.data : ownedQuery.data) as
		| QueryDataMap
		| undefined;
	const isFiltering = api?.kind === 'shared' ? sharedQuery.isFetching : ownedQuery.isFetching;

	return {
		filters,
		selections,
		setSelection,
		clearSelections,
		hasActiveFilters,
		isFiltering,
		queryData: hasActiveFilters ? (filteredQueryData ?? baselineQueryData ?? null) : (baselineQueryData ?? null),
	};
}

function dedupeFilters(filters: ParsedFilterBlock[]): ParsedFilterBlock[] {
	const seen = new Set<string>();
	return filters.filter((filter) => {
		if (seen.has(filter.id)) {
			return false;
		}
		seen.add(filter.id);
		return true;
	});
}

function isEmptySelection(selection: StoryFilterSelection): boolean {
	return typeof selection === 'string'
		? selection.trim() === ''
		: selection.length === 0 || selection.every((value) => value.trim() === '');
}

function readSelectionsFromUrl(filters: ParsedFilterBlock[]): StoryFilterSelections {
	if (typeof window === 'undefined') {
		return {};
	}

	const params = new URLSearchParams(window.location.search);
	const selections: StoryFilterSelections = {};
	for (const filter of filters) {
		const raw = params.get(`${FILTER_PARAM_PREFIX}${filter.id}`);
		if (raw === null) {
			continue;
		}
		if (filter.filterType === 'select' || filter.filterType === 'search') {
			selections[filter.id] = raw;
			continue;
		}
		try {
			const parsed = JSON.parse(raw);
			if (Array.isArray(parsed) && parsed.every((item) => typeof item === 'string')) {
				selections[filter.id] = parsed;
			}
		} catch {
			// ignore malformed URL values
		}
	}
	return selections;
}

function writeSelectionsToUrl(selections: StoryFilterSelections, filters: ParsedFilterBlock[]) {
	if (typeof window === 'undefined') {
		return;
	}

	const url = new URL(window.location.href);
	for (const key of [...url.searchParams.keys()]) {
		if (key.startsWith(FILTER_PARAM_PREFIX)) {
			url.searchParams.delete(key);
		}
	}

	const filterById = new Map(filters.map((filter) => [filter.id, filter]));
	for (const [filterId, selection] of Object.entries(selections)) {
		const filter = filterById.get(filterId);
		if (!filter || isEmptySelection(selection)) {
			continue;
		}
		const key = `${FILTER_PARAM_PREFIX}${filterId}`;
		if (filter.filterType === 'select' || filter.filterType === 'search') {
			url.searchParams.set(key, selection as string);
		} else {
			url.searchParams.set(key, JSON.stringify(selection));
		}
	}

	window.history.replaceState(window.history.state, '', `${url.pathname}${url.search}${url.hash}`);
}

import { FilterX, ListFilter, Loader2 } from 'lucide-react';
import { useQuery } from '@tanstack/react-query';
import type { StoryFilterSelection } from '@nao/shared/sql-template';
import type { ParsedFilterBlock } from '@nao/shared/story-segments';

import type { StoryFilterApi } from '@/hooks/use-story-filters';
import { Button } from '@/components/ui/button';
import {
	DropdownMenu,
	DropdownMenuCheckboxItem,
	DropdownMenuContent,
	DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import { Input } from '@/components/ui/input';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { trpc } from '@/main';

export function StoryFilterBar({
	filters,
	selections,
	onSelectionChange,
	onClear,
	api,
	isFiltering,
}: {
	filters: ParsedFilterBlock[];
	selections: Record<string, StoryFilterSelection>;
	onSelectionChange: (filterId: string, selection: StoryFilterSelection) => void;
	onClear: () => void;
	api?: StoryFilterApi | null;
	isFiltering?: boolean;
}) {
	if (filters.length === 0) {
		return null;
	}

	const hasActiveFilters = Object.values(selections).some((selection) =>
		typeof selection === 'string' ? Boolean(selection) : selection.some(Boolean),
	);

	return (
		<div className='flex flex-wrap items-end gap-3 rounded-lg border bg-muted/20 p-3'>
			<div className='flex h-8 items-center gap-2 text-sm font-medium text-muted-foreground'>
				{isFiltering ? <Loader2 className='size-4 animate-spin' /> : <ListFilter className='size-4' />}
				Filters
			</div>
			{filters.map((filter) => (
				<StoryFilterControl
					key={filter.id}
					filter={filter}
					selection={selections[filter.id]}
					onChange={(selection) => onSelectionChange(filter.id, selection)}
					api={api}
				/>
			))}
			{hasActiveFilters && (
				<Button variant='ghost' size='sm' className='h-8 gap-1.5' onClick={onClear}>
					<FilterX className='size-3.5' />
					Clear
				</Button>
			)}
		</div>
	);
}

function StoryFilterControl({
	filter,
	selection,
	onChange,
	api,
}: {
	filter: ParsedFilterBlock;
	selection: StoryFilterSelection | undefined;
	onChange: (selection: StoryFilterSelection) => void;
	api?: StoryFilterApi | null;
}) {
	const options = useFilterOptions(filter, api);

	return (
		<label className='flex min-w-36 flex-col gap-1'>
			<span className='text-xs font-medium text-muted-foreground'>{filter.label}</span>
			{filter.filterType === 'select' ? (
				<Select
					value={typeof selection === 'string' && selection ? selection : '__all__'}
					onValueChange={(value) => onChange(value === '__all__' ? '' : value)}
				>
					<SelectTrigger className='h-8 min-w-36 bg-background'>
						<SelectValue placeholder='All' />
					</SelectTrigger>
					<SelectContent>
						<SelectItem value='__all__'>All</SelectItem>
						{options.map((option) => (
							<SelectItem key={option} value={option}>
								{option}
							</SelectItem>
						))}
					</SelectContent>
				</Select>
			) : filter.filterType === 'multi_select' ? (
				<MultiSelectFilter
					options={options}
					value={Array.isArray(selection) ? selection : []}
					onChange={onChange}
				/>
			) : filter.filterType === 'date_range' ? (
				<RangeFilter value={Array.isArray(selection) ? selection : []} onChange={onChange} />
			) : (
				<Input
					type='search'
					className='h-8 min-w-44 bg-background'
					placeholder='Search'
					value={typeof selection === 'string' ? selection : ''}
					onChange={(event) => onChange(event.target.value)}
				/>
			)}
		</label>
	);
}

function MultiSelectFilter({
	options,
	value,
	onChange,
}: {
	options: string[];
	value: string[];
	onChange: (value: string[]) => void;
}) {
	return (
		<DropdownMenu>
			<DropdownMenuTrigger asChild>
				<Button variant='outline' size='sm' className='h-8 min-w-36 justify-between bg-background font-normal'>
					{value.length > 0 ? `${value.length} selected` : 'All'}
				</Button>
			</DropdownMenuTrigger>
			<DropdownMenuContent className='max-h-64 min-w-48'>
				{options.map((option) => (
					<DropdownMenuCheckboxItem
						key={option}
						checked={value.includes(option)}
						onSelect={(event) => event.preventDefault()}
						onCheckedChange={(checked) =>
							onChange(checked ? [...value, option] : value.filter((candidate) => candidate !== option))
						}
					>
						{option}
					</DropdownMenuCheckboxItem>
				))}
			</DropdownMenuContent>
		</DropdownMenu>
	);
}

function RangeFilter({ value, onChange }: { value: string[]; onChange: (value: string[]) => void }) {
	return (
		<div className='flex items-center gap-1'>
			<Input
				type='date'
				className='h-8 w-36 bg-background'
				value={value[0] ?? ''}
				onChange={(event) => onChange([event.target.value, value[1] ?? ''])}
				aria-label='From'
			/>
			<span className='text-xs text-muted-foreground'>to</span>
			<Input
				type='date'
				className='h-8 w-36 bg-background'
				value={value[1] ?? ''}
				onChange={(event) => onChange([value[0] ?? '', event.target.value])}
				aria-label='To'
			/>
		</div>
	);
}

function useFilterOptions(filter: ParsedFilterBlock, api?: StoryFilterApi | null): string[] {
	const ownedQuery = useQuery({
		...trpc.story.getFilterOptions.queryOptions({
			chatId: api?.kind === 'owned' ? api.chatId : '',
			storySlug: api?.kind === 'owned' ? api.storySlug : '',
			filterId: filter.id,
		}),
		enabled: Boolean(api?.kind === 'owned' && (filter.filterType === 'select' || filter.filterType === 'multi_select')),
	});

	const sharedQuery = useQuery({
		...trpc.storyShare.getFilterOptions.queryOptions({
			shareId: api?.kind === 'shared' ? api.shareId : '',
			filterId: filter.id,
		}),
		enabled: Boolean(
			api?.kind === 'shared' && (filter.filterType === 'select' || filter.filterType === 'multi_select'),
		),
	});

	return (api?.kind === 'shared' ? sharedQuery.data?.options : ownedQuery.data?.options) ?? [];
}

import { useMemo, useState } from 'react';
import { parseStoryTabs, stripStoryTabsMarkup } from '@nao/shared/story-tabs';
