import { TRPCError } from '@trpc/server';

export function assertSafeSqlIdentifier(value: string, kind: 'table' | 'column'): string {
	const unquoted = /^[A-Za-z_][A-Za-z0-9_]*(\.[A-Za-z_][A-Za-z0-9_]*)*$/;
	const quoted = /^"[^"]+"(\."[^"]+")*$/;
	if (!unquoted.test(value) && !quoted.test(value)) {
		throw new TRPCError({
			code: 'BAD_REQUEST',
			message: `Invalid filter ${kind} identifier "${value}".`,
		});
	}
	return value;
}

