import { executeSql } from '@nao/shared/tools';
import { and, eq, sql } from 'drizzle-orm';

import s from '../db/abstractSchema';
import { db } from '../db/db';
import dbConfig, { Dialect } from '../db/dbConfig';
import { takeFirstOrThrow } from '../utils/queries';

const EXECUTE_SQL_TOOL_NAME = 'execute_sql';

function queryIdFilter(queryId: string) {
	return dbConfig.dialect === Dialect.Postgres
		? sql`${s.messagePart.toolOutput}->>'id' = ${queryId}`
		: sql`json_extract(${s.messagePart.toolOutput}, '$.id') = ${queryId}`;
}

export async function getExecuteSqlOwnerByQueryId(
	queryId: string,
): Promise<{ projectId: string; userId: string; chatId: string; toolCallId: string } | null> {
	const [row] = await db
		.select({
			projectId: s.chat.projectId,
			userId: s.chat.userId,
			chatId: s.chat.id,
			toolCallId: s.messagePart.toolCallId,
		})
		.from(s.messagePart)
		.innerJoin(s.chatMessage, eq(s.messagePart.messageId, s.chatMessage.id))
		.innerJoin(s.chat, eq(s.chatMessage.chatId, s.chat.id))
		.where(and(eq(s.messagePart.toolName, EXECUTE_SQL_TOOL_NAME), queryIdFilter(queryId)))
		.execute();

	return row?.toolCallId ? row : null;
}

export async function getExecuteSqlPartByQueryIdInChat(
	chatId: string,
	queryId: string,
): Promise<{ toolCallId: string; toolInput: executeSql.Input; toolOutput: executeSql.Output } | null> {
	const [row] = await db
		.select({
			toolCallId: s.messagePart.toolCallId,
			toolInput: s.messagePart.toolInput,
			toolOutput: s.messagePart.toolOutput,
		})
		.from(s.messagePart)
		.innerJoin(s.chatMessage, eq(s.messagePart.messageId, s.chatMessage.id))
		.where(
			and(
				eq(s.chatMessage.chatId, chatId),
				eq(s.messagePart.toolName, EXECUTE_SQL_TOOL_NAME),
				queryIdFilter(queryId),
			),
		)
		.execute();

	if (!row?.toolCallId || !row.toolInput || !row.toolOutput) {
		return null;
	}

	return {
		toolCallId: row.toolCallId,
		toolInput: executeSql.InputSchema.parse(row.toolInput),
		toolOutput: executeSql.OutputSchema.parse(row.toolOutput),
	};
}

export async function updateExecuteSqlPart(
	toolCallId: string,
	toolInput: executeSql.Input,
	toolOutput: executeSql.Output,
): Promise<void> {
	await takeFirstOrThrow(
		db
			.update(s.messagePart)
			.set({ toolInput, toolOutput })
			.where(and(eq(s.messagePart.toolCallId, toolCallId), eq(s.messagePart.toolName, EXECUTE_SQL_TOOL_NAME)))
			.returning({ toolCallId: s.messagePart.toolCallId })
			.execute(),
	);
}

import { stripSqlFilterBlocks } from '@nao/shared/sql-template';
import type { executeSql } from '@nao/shared/tools';
import { TRPCError } from '@trpc/server';

import { executeQuery } from '../agents/tools/execute-sql';
import * as chatQueries from '../queries/chat.queries';
import {
	getExecuteSqlOwnerByQueryId,
	getExecuteSqlPartByQueryIdInChat,
	updateExecuteSqlPart,
} from '../queries/execute-sql.queries';
import * as projectQueries from '../queries/project.queries';
import type { ToolContext } from '../types/tools';

export async function updateSqlQueryInChat(opts: {
	queryId: string;
	sqlQuery: string;
	databaseId?: string;
	name?: string;
	userId: string;
}): Promise<{ input: executeSql.Input; output: executeSql.Output; toolCallId: string; chatId: string }> {
	const owner = await getExecuteSqlOwnerByQueryId(opts.queryId);
	if (!owner) {
		throw new TRPCError({ code: 'NOT_FOUND', message: `Query ${opts.queryId} not found.` });
	}
	if (owner.userId !== opts.userId) {
		throw new TRPCError({ code: 'FORBIDDEN', message: 'You are not authorized to edit this query.' });
	}

	const existing = await getExecuteSqlPartByQueryIdInChat(owner.chatId, opts.queryId);
	if (!existing) {
		throw new TRPCError({ code: 'NOT_FOUND', message: `Query ${opts.queryId} not found.` });
	}

	const project = await projectQueries.retrieveProjectById(owner.projectId);
	if (!project.path) {
		throw new TRPCError({ code: 'INTERNAL_SERVER_ERROR', message: 'Project path not configured.' });
	}

	const agentSettings = await chatQueries.getChatAgentSettings(owner.chatId);
	const envVars = await projectQueries.getEnvVars(owner.projectId);
	const context: ToolContext = {
		projectFolder: project.path,
		chatId: owner.chatId,
		userId: opts.userId,
		projectId: owner.projectId,
		agentSettings,
		envVars,
		azureAccessToken: null,
		queryResults: new Map(),
		generatedArtifacts: { charts: [], stories: [] },
	};

	const input: executeSql.Input = {
		sql_query: opts.sqlQuery,
		database_id: opts.databaseId ?? existing.toolInput.database_id,
		name: opts.name ?? existing.toolInput.name,
	};

	const output = await executeQuery({ ...input, query_id: opts.queryId as `query_${string}` }, context);
	await updateExecuteSqlPart(existing.toolCallId, input, output);

	return { input, output, toolCallId: existing.toolCallId, chatId: owner.chatId };
}

export async function updateSqlQueryFromAgent(
	context: ToolContext,
	input: executeSql.Input & { query_id: `query_${string}` },
): Promise<executeSql.Output> {
	const existing = await getExecuteSqlPartByQueryIdInChat(context.chatId, input.query_id);
	if (!existing) {
		throw new Error(
			`Query ${input.query_id} not found in this chat. Use execute_sql without query_id to create a new query.`,
		);
	}

	const nextInput: executeSql.Input = {
		sql_query: input.sql_query,
		database_id: input.database_id ?? existing.toolInput.database_id,
		name: input.name ?? existing.toolInput.name,
	};

	const output = await executeQuery({ ...nextInput, query_id: input.query_id }, context);
	await updateExecuteSqlPart(existing.toolCallId, nextInput, output);
	return output;
}

export function assertSqlQueryEditable(sqlQuery: string): void {
	if (!sqlQuery.trim()) {
		throw new TRPCError({ code: 'BAD_REQUEST', message: 'SQL query cannot be empty.' });
	}
	if (stripSqlFilterBlocks(sqlQuery).trim() === '') {
		throw new TRPCError({ code: 'BAD_REQUEST', message: 'SQL query cannot be empty after removing filter blocks.' });
	}
}

