import { stripSqlFilterBlocks } from '@nao/shared/sql-template';
import type { executeSql } from '@nao/shared/tools';
import { TRPCError } from '@trpc/server';

import { executeQuery } from '../agents/tools/execute-sql';
import {
	getExecuteSqlOwnerByQueryId,
	getExecuteSqlPartByQueryIdInChat,
	updateExecuteSqlPart,
} from '../queries/execute-sql.queries';
import * as projectQueries from '../queries/project.queries';
import type { ToolContext } from '../types/tools';

export async function updateSqlQueryInChat(opts: {
	queryId: string;
	sqlQuery: string;
	databaseId?: string;
	name?: string;
	userId: string;
}): Promise<{ input: executeSql.Input; output: executeSql.Output; toolCallId: string; chatId: string }> {
	assertSqlQueryEditable(opts.sqlQuery);

	const owner = await getExecuteSqlOwnerByQueryId(opts.queryId);
	if (!owner) {
		throw new TRPCError({ code: 'NOT_FOUND', message: `Query ${opts.queryId} not found.` });
	}
	if (owner.userId !== opts.userId) {
		throw new TRPCError({ code: 'FORBIDDEN', message: 'You are not authorized to edit this query.' });
	}

	const existing = await getExecuteSqlPartByQueryIdInChat(owner.chatId, opts.queryId);
	if (!existing) {
		throw new TRPCError({ code: 'NOT_FOUND', message: `Query ${opts.queryId} not found.` });
	}

	const project = await projectQueries.retrieveProjectById(owner.projectId);
	if (!project.path) {
		throw new TRPCError({ code: 'INTERNAL_SERVER_ERROR', message: 'Project path not configured.' });
	}

	const agentSettings = await projectQueries.getAgentSettings(owner.projectId);
	const envVars = await projectQueries.getEnvVars(owner.projectId);
	const context: ToolContext = {
		projectFolder: project.path,
		chatId: owner.chatId,
		userId: opts.userId,
		projectId: owner.projectId,
		agentSettings,
		envVars,
		azureAccessToken: null,
		queryResults: new Map(),
		generatedArtifacts: { charts: [], stories: [] },
	};

	const input: executeSql.Input = {
		sql_query: opts.sqlQuery,
		database_id: opts.databaseId ?? existing.toolInput.database_id,
		name: opts.name ?? existing.toolInput.name,
	};

	const output = await executeQuery({ ...input, query_id: opts.queryId as `query_${string}` }, context);
	await updateExecuteSqlPart(existing.toolCallId, input, output);

	return { input, output, toolCallId: existing.toolCallId, chatId: owner.chatId };
}

export function assertSqlQueryEditable(sqlQuery: string): void {
	if (!sqlQuery.trim()) {
		throw new TRPCError({ code: 'BAD_REQUEST', message: 'SQL query cannot be empty.' });
	}
	if (stripSqlFilterBlocks(sqlQuery).trim() === '') {
		throw new TRPCError({ code: 'BAD_REQUEST', message: 'SQL query cannot be empty after removing filter blocks.' });
	}
}

import { stripSqlFilterBlocks } from '@nao/shared/sql-template';
import type { executeSql } from '@nao/shared/tools';
import { executeSql as schemas } from '@nao/shared/tools';

import { ExecuteSqlOutput, renderToModelOutput } from '../../components/tool-outputs';
import { env } from '../../env';
import {
	getExecuteSqlPartByQueryIdInChat,
	updateExecuteSqlPart,
} from '../../queries/execute-sql.queries';
import { ToolContext } from '../../types/tools';
import { detectQueryRowLimit, isReadOnlySqlQuery } from '../../utils/sql-filter';
import { createTool } from '../../utils/tools';
import { queryAppDb } from './query-app-db';

export async function executeQuery(
	{ sql_query, database_id, query_id }: executeSql.Input,
	context: ToolContext,
): Promise<executeSql.Output> {
	const effectiveSql = stripSqlFilterBlocks(sql_query);
	const writePermEnabled = context.agentSettings?.sql?.dangerouslyWritePermEnabled ?? false;
	if (!writePermEnabled && !(await isReadOnlySqlQuery(effectiveSql))) {
		throw new Error(
			'Write SQL operations are disabled. Only SELECT queries are allowed. ' +
				'Enable "Dangerous write permissions" in the admin panel to allow INSERT, UPDATE, DELETE and DDL queries.',
		);
	}

	if (context.adminMode) {
		return executeAppDbQuery(effectiveSql, context, query_id);
	}

	const naoProjectFolder = context.projectFolder;
	const envVars = context.envVars;
	const response = await fetch(`http://localhost:${env.FASTAPI_PORT}/execute_sql`, {
		method: 'POST',
		headers: {
			'Content-Type': 'application/json',
		},
		body: JSON.stringify({
			sql: effectiveSql,
			nao_project_folder: naoProjectFolder,
			...(database_id && { database_id }),
			...(Object.keys(envVars).length > 0 && { env_vars: envVars }),
			...(context.azureAccessToken && { azure_access_token: context.azureAccessToken }),
		}),
	});

	if (!response.ok) {
		const errorData = await response.json().catch(() => ({ detail: response.statusText }));
		throw new Error(`Error executing SQL query: ${JSON.stringify(errorData.detail)}`);
	}

	const data = await response.json();
	const id = query_id ?? (`query_${crypto.randomUUID().slice(0, 8)}` as const);

	context.queryResults.set(id, { columns: data.columns, data: data.data });

	const appliedLimit = detectQueryRowLimit(effectiveSql);

	return {
		_version: '1',
		...data,
		id,
		...(appliedLimit !== null && { applied_limit: appliedLimit }),
	};
}

async function executeAppDbQuery(
	sqlQuery: string,
	context: ToolContext,
	queryId?: `query_${string}`,
): Promise<executeSql.Output> {
	const { columns, rows } = await queryAppDb(context.projectId, sqlQuery);
	const id = queryId ?? (`query_${crypto.randomUUID().slice(0, 8)}` as const);
	context.queryResults.set(id, { columns, data: rows });
	const appliedLimit = detectQueryRowLimit(sqlQuery);
	return {
		_version: '1',
		data: rows,
		row_count: rows.length,
		columns,
		id,
		...(appliedLimit !== null && { applied_limit: appliedLimit }),
	};
}

async function updateExistingQuery(
	input: executeSql.Input & { query_id: `query_${string}` },
	context: ToolContext,
): Promise<executeSql.Output> {
	const existing = await getExecuteSqlPartByQueryIdInChat(context.chatId, input.query_id);
	if (!existing) {
		throw new Error(
			`Query ${input.query_id} not found in this chat. Use execute_sql without query_id to create a new query.`,
		);
	}

	const nextInput: executeSql.Input = {
		sql_query: input.sql_query,
		database_id: input.database_id ?? existing.toolInput.database_id,
		name: input.name ?? existing.toolInput.name,
	};

	const output = await executeQuery({ ...nextInput, query_id: input.query_id }, context);
	await updateExecuteSqlPart(existing.toolCallId, nextInput, output);
	return output;
}

export default createTool<executeSql.Input, executeSql.Output>({
	description: [
		'Execute a SQL query against the connected database and return the results. If multiple databases are configured, specify the database_id.',
		'Story filters may be embedded as SQL template blocks that are stripped when this tool runs in chat:',
		'WHERE 1 = 1 {% filter country %} AND country IN ({{ filters.country.sql }}) {% endfilter %}.',
		'To edit a previous query in-place (keep the same query_id for charts/stories), pass query_id from an earlier execute_sql result.',
		'Prefer query_id when adding story filter templates so existing <chart>/<table> tags keep working.',
	].join(' '),
	inputSchema: schemas.InputSchema,
	outputSchema: schemas.OutputSchema,
	execute: async (input, context) => {
		if (input.query_id) {
			return updateExistingQuery({ ...input, query_id: input.query_id }, context);
		}
		return executeQuery(input, context);
	},
	toModelOutput: ({ output }) => renderToModelOutput(ExecuteSqlOutput({ output }), output),
});

import { useEffect, useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import type { executeSql } from '@nao/shared/tools';
import type { UIMessage, UIToolPart } from '@nao/backend/chat';

import { useAgentContext } from '@/contexts/agent.provider';
import { Button } from '@/components/ui/button';
import {
	Dialog,
	DialogContent,
	DialogDescription,
	DialogFooter,
	DialogHeader,
	DialogTitle,
} from '@/components/ui/dialog';
import { Textarea } from '@/components/ui/textarea';
import { trpc } from '@/main';

interface ExecuteSqlEditDialogProps {
	open: boolean;
	onOpenChange: (open: boolean) => void;
	queryId: `query_${string}`;
	input: executeSql.Input;
}

export function ExecuteSqlEditDialog({ open, onOpenChange, queryId, input }: ExecuteSqlEditDialogProps) {
	const queryClient = useQueryClient();
	const { messages, setMessages } = useAgentContext();
	const [sqlQuery, setSqlQuery] = useState(input.sql_query);

	useEffect(() => {
		if (open) {
			setSqlQuery(input.sql_query);
		}
	}, [open, input.sql_query]);

	const updateMutation = useMutation(
		trpc.sql.updateQuery.mutationOptions({
			onSuccess: () => {
				queryClient.invalidateQueries({ queryKey: [['chat', 'get']] });
			},
		}),
	);

	const handleSave = async () => {
		const previousMessages = messages;
		const optimisticInput: executeSql.Input = {
			...input,
			sql_query: sqlQuery,
		};
		setMessages(applyExecuteSqlInputToMessages(previousMessages, queryId, optimisticInput));
		try {
			const result = await updateMutation.mutateAsync({
				queryId,
				sql_query: sqlQuery,
				database_id: input.database_id,
				name: input.name,
			});
			setMessages(applyExecuteSqlResultToMessages(previousMessages, queryId, result.input, result.output));
			onOpenChange(false);
		} catch (err) {
			setMessages(previousMessages);
			throw err;
		}
	};

	return (
		<Dialog open={open} onOpenChange={onOpenChange}>
			<DialogContent className='sm:max-w-2xl'>
				<DialogHeader>
					<DialogTitle>Edit SQL query</DialogTitle>
					<DialogDescription>
						Update and re-run this query. The query id stays the same so charts and stories keep working.
					</DialogDescription>
				</DialogHeader>
				<Textarea
					value={sqlQuery}
					onChange={(event) => setSqlQuery(event.target.value)}
					className='min-h-56 font-mono text-sm'
					spellCheck={false}
				/>
				<DialogFooter>
					<Button variant='ghost' onClick={() => onOpenChange(false)} disabled={updateMutation.isPending}>
						Cancel
					</Button>
					<Button onClick={handleSave} disabled={updateMutation.isPending || !sqlQuery.trim()}>
						{updateMutation.isPending ? 'Running…' : 'Save & run'}
					</Button>
				</DialogFooter>
			</DialogContent>
		</Dialog>
	);
}

function applyExecuteSqlInputToMessages(
	messages: UIMessage[],
	queryId: string,
	input: executeSql.Input,
): UIMessage[] {
	return messages.map((message) => {
		let changed = false;
		const parts = message.parts.map((part) => {
			if (part.type !== 'tool-execute_sql') {
				return part;
			}
			const toolPart = part as UIToolPart<'execute_sql'>;
			if (toolPart.output?.id !== queryId) {
				return part;
			}
			changed = true;
			return { ...toolPart, input } as typeof part;
		});
		return changed ? { ...message, parts } : message;
	});
}

function applyExecuteSqlResultToMessages(
	messages: UIMessage[],
	queryId: string,
	input: executeSql.Input,
	output: executeSql.Output,
): UIMessage[] {
	return messages.map((message) => {
		let changed = false;
		const parts = message.parts.map((part) => {
			if (part.type !== 'tool-execute_sql') {
				return part;
			}
			const toolPart = part as UIToolPart<'execute_sql'>;
			if (toolPart.output?.id !== queryId) {
				return part;
			}
			changed = true;
			return { ...toolPart, input, output } as typeof part;
		});
		return changed ? { ...message, parts } : message;
	});
}

import { useState } from 'react';
import { useMutation } from '@tanstack/react-query';
import { ArrowUpRight, Code, Copy, Download, Palette, Pencil, Table as TableIcon } from 'lucide-react';
import { ToolCallWrapper } from './tool-call-wrapper';
import { TableFormatEditDialog } from './display-table-edit-dialog';
import { ExecuteSqlEditDialog } from './execute-sql-edit-dialog';
import { SqlQueryDisplay } from './sql-query-display';
import { SqlResultDisplay } from './sql-result-display';
import type { ToolCallComponentProps } from '.';
import type { ColumnConditionalFormats } from '@nao/shared/conditional-formatting';
import { useOptionalAgentContext } from '@/contexts/agent.provider';
import { useSidePanel } from '@/contexts/side-panel';
import { useToolCallContext } from '@/contexts/tool-call';
import { SidePanelContent } from '@/components/side-panel/sql-editor';
import { downloadCsv, tableToCsv } from '@/lib/table-export';
import { trpc } from '@/main';

type ViewMode = 'results' | 'query';

export const ExecuteSqlToolCall = ({
	toolPart: { output, input, state, toolCallId },
}: ToolCallComponentProps<'execute_sql'>) => {
	const [viewMode, setViewMode] = useState<ViewMode>('results');
	const [conditionalFormats, setConditionalFormats] = useState<ColumnConditionalFormats>({});
	const [isFormatOpen, setIsFormatOpen] = useState(false);
	const [isEditOpen, setIsEditOpen] = useState(false);
	const { isSettled } = useToolCallContext();
	const { open: openSidePanel } = useSidePanel();
	const agent = useOptionalAgentContext();
	const chatId = agent?.chatId;
	const isEditable = Boolean(agent && !agent.isReadonly && !agent.isRunning && output?.id && input?.sql_query);
	const logDownload = useMutation(trpc.analyticsEvent.logChatDownload.mutationOptions());

	const actions = [
		{
			id: 'results',
			label: <TableIcon className='size-3 text-muted-foreground/70' strokeWidth={2.25} />,
			expandOnClick: true,
			isActive: viewMode === 'results',
			onClick: () => setViewMode('results'),
			title: 'View results',
		},
		{
			id: 'query',
			label: <Code className='size-3 text-muted-foreground/70' strokeWidth={2.25} />,
			expandOnClick: true,
			isActive: viewMode === 'query',
			onClick: () => setViewMode('query'),
			title: 'View query',
		},
		...(isEditable
			? [
					{
						id: 'edit',
						label: <Pencil className='size-3 text-muted-foreground/70' strokeWidth={2.25} />,
						onClick: () => setIsEditOpen(true),
						title: 'Edit SQL query',
					},
				]
			: []),
		{
			id: 'format',
			label: <Palette className='size-3 text-muted-foreground/70' strokeWidth={2.25} />,
			onClick: () => {
				if (!output) {
					return;
				}
				setViewMode('results');
				setIsFormatOpen(true);
			},
			title: 'Conditional formatting',
		},
		{
			id: 'copy',
			label: <Copy className='size-3 text-muted-foreground/70' strokeWidth={2.25} />,
			onClick: () => {
				navigator.clipboard.writeText(input?.sql_query ?? '');
			},
			title: 'Copy query',
		},
		{
			id: 'download',
			label: <Download className='size-3 text-muted-foreground/70' strokeWidth={2.25} />,
			onClick: () => {
				if (!output) {
					return;
				}
				downloadCsv(
					`${input?.name || 'query'}.csv`,
					tableToCsv(output.columns, output.data as Record<string, unknown>[]),
				);
				if (chatId) {
					logDownload.mutate({ chatId, format: 'csv', queryId: toolCallId, title: input?.name });
				}
			},
			title: 'Download results as CSV',
		},
		{
			id: 'expand',
			label: <ArrowUpRight className='size-3 text-muted-foreground/70' strokeWidth={2.25} />,
			onClick: () => {
				if (state === 'input-streaming' || !output || !input) {
					return;
				}
				openSidePanel(<SidePanelContent input={input} output={output} />);
			},
			title: 'Open in side panel',
		},
	];

	return (
		<ToolCallWrapper
			defaultExpanded={false}
			overrideError={viewMode === 'query'}
			title={
				<span className='flex items-baseline gap-2.5'>
					<span className='text-foreground'>SQL</span>
					<span className='text-xs text-muted-foreground truncate'>{input?.name ?? input?.sql_query}</span>
				</span>
			}
			badge={output?.row_count && `${output.row_count} rows`}
			actions={isSettled ? actions : []}
		>
			{viewMode === 'query' && input?.sql_query ? (
				<SqlQueryDisplay query={input.sql_query} />
			) : output ? (
				<>
					<SqlResultDisplay output={output} conditionalFormats={conditionalFormats} />
					<TableFormatEditDialog
						open={isFormatOpen}
						onOpenChange={setIsFormatOpen}
						columns={output.columns}
						data={output.data as Record<string, unknown>[]}
						formats={conditionalFormats}
						onSave={async (next) => setConditionalFormats(next)}
						description='Apply conditional formatting to columns of this result.'
					/>
				</>
			) : (
				<div className='p-4 text-center text-foreground/50 text-sm'>Executing query...</div>
			)}
			{isEditable && input && output?.id && (
				<ExecuteSqlEditDialog
					open={isEditOpen}
					onOpenChange={setIsEditOpen}
					queryId={output.id}
					input={input}
				/>
			)}
		</ToolCallWrapper>
	);
};

