import type { executeSql } from '@nao/shared/tools';
import type { UIMessage, UIToolPart } from '@nao/backend/chat';

export function applyExecuteSqlInputToMessages(
	messages: UIMessage[],
	queryId: string,
	input: executeSql.Input,
): UIMessage[] {
	return messages.map((message) => {
		let changed = false;
		const parts = message.parts.map((part) => {
			if (part.type !== 'tool-execute_sql') {
				return part;
			}
			const toolPart = part as UIToolPart<'execute_sql'>;
			if (toolPart.output?.id !== queryId) {
				return part;
			}
			changed = true;
			return { ...toolPart, input } as typeof part;
		});
		return changed ? { ...message, parts } : message;
	});
}

export function applyExecuteSqlResultToMessages(
	messages: UIMessage[],
	queryId: string,
	input: executeSql.Input,
	output: executeSql.Output,
): UIMessage[] {
	return messages.map((message) => {
		let changed = false;
		const parts = message.parts.map((part) => {
			if (part.type !== 'tool-execute_sql') {
				return part;
			}
			const toolPart = part as UIToolPart<'execute_sql'>;
			if (toolPart.output?.id !== queryId) {
				return part;
			}
			changed = true;
			return { ...toolPart, input, output } as typeof part;
		});
		return changed ? { ...message, parts } : message;
	});
}

import { useState } from 'react';
import { Editor } from '@monaco-editor/react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { Loader2, Play, Save } from 'lucide-react';
import { ResizableSeparator, ResizablePanel, ResizablePanelGroup } from '../ui/resizable';
import type { executeSql } from '@nao/shared/tools';

import { useOptionalAgentContext } from '@/contexts/agent.provider';
import { SidePanelHeader } from '@/components/side-panel/side-panel-header';
import { TableDisplay } from '@/components/tool-calls/display-table';
import { Button } from '@/components/ui/button';
import { applyExecuteSqlResultToMessages } from '@/lib/execute-sql-messages';
import { formatSQL } from '@/lib/sql-formatter';
import { trpc } from '@/main';

export const SidePanelContent = ({
	input,
	output,
	editable = false,
}: {
	input: executeSql.Input;
	output: executeSql.Output;
	editable?: boolean;
}) => {
	const queryClient = useQueryClient();
	const agent = useOptionalAgentContext();
	const [sqlQuery, setSqlQuery] = useState(input.sql_query);
	const [previewOutput, setPreviewOutput] = useState<executeSql.Output>(output);
	const [error, setError] = useState<string | null>(null);

	const canEdit = Boolean(editable && output.id && agent && !agent.isReadonly);
	const isDirty = sqlQuery !== input.sql_query;

	const previewMutation = useMutation(
		trpc.sql.previewQuery.mutationOptions({
			onSuccess: (result) => {
				setPreviewOutput(result);
				setError(null);
			},
			onError: (err) => {
				setError(err.message);
			},
		}),
	);

	const saveMutation = useMutation(
		trpc.sql.updateQuery.mutationOptions({
			onSuccess: (result) => {
				setPreviewOutput(result.output);
				setSqlQuery(result.input.sql_query);
				setError(null);
				if (agent) {
					agent.setMessages(
						applyExecuteSqlResultToMessages(agent.messages, result.output.id, result.input, result.output),
					);
				}
				queryClient.invalidateQueries({ queryKey: [['chat', 'get']] });
			},
			onError: (err) => {
				setError(err.message);
			},
		}),
	);

	const isBusy = previewMutation.isPending || saveMutation.isPending;

	const handleRun = () => {
		if (!output.id || !sqlQuery.trim()) {
			return;
		}
		setError(null);
		previewMutation.mutate({
			queryId: output.id,
			sql_query: sqlQuery,
			database_id: input.database_id,
			name: input.name,
		});
	};

	const handleSaveAndRun = () => {
		if (!output.id || !sqlQuery.trim()) {
			return;
		}
		setError(null);
		saveMutation.mutate({
			queryId: output.id,
			sql_query: sqlQuery,
			database_id: input.database_id,
			name: input.name,
		});
	};

	return (
		<div className='flex h-full min-h-0 flex-col bg-background'>
			<SidePanelHeader title={input.name ?? input.sql_query} />

			{canEdit && (
				<div className='flex shrink-0 items-center justify-between gap-2 border-b px-4 py-2'>
					<div className='text-xs text-muted-foreground'>
						{isDirty ? 'Unsaved changes' : 'Edit SQL, then run or save'}
					</div>
					<div className='flex items-center gap-2'>
						<Button
							variant='outline'
							size='sm'
							className='h-8 gap-1.5'
							onClick={handleRun}
							disabled={isBusy || !sqlQuery.trim()}
						>
							{previewMutation.isPending ? (
								<Loader2 className='size-3.5 animate-spin' />
							) : (
								<Play className='size-3.5' />
							)}
							Run
						</Button>
						<Button
							size='sm'
							className='h-8 gap-1.5'
							onClick={handleSaveAndRun}
							disabled={isBusy || !sqlQuery.trim()}
						>
							{saveMutation.isPending ? (
								<Loader2 className='size-3.5 animate-spin' />
							) : (
								<Save className='size-3.5' />
							)}
							Save & run
						</Button>
					</div>
				</div>
			)}

			{error && (
				<div className='shrink-0 border-b bg-destructive/10 px-4 py-2 text-sm text-destructive'>{error}</div>
			)}

			<ResizablePanelGroup
				orientation='vertical'
				defaultLayout={{ sql: 1 / 4, results: 1 }}
				className='min-h-0 flex-1'
			>
				<ResizablePanel id='sql' minSize={100} className='relative w-full group'>
					<div className='w-full h-full overflow-auto [&_span]:font-mono pl-2'>
						<Editor
							value={canEdit ? sqlQuery : formatSQL(input.sql_query, output.dialect)}
							onChange={canEdit ? (value) => setSqlQuery(value ?? '') : undefined}
							language='sql'
							theme='light'
							options={{
								readOnly: !canEdit,
								minimap: {
									enabled: false,
								},
								folding: false,
								lineNumbers: canEdit ? 'on' : 'off',
								scrollbar: {
									horizontal: 'hidden',
									vertical: 'hidden',
								},
								scrollBeyondLastLine: false,
								padding: {
									top: 16,
									bottom: 16,
								},
								wordWrap: 'on',
							}}
						/>
					</div>
				</ResizablePanel>

				<ResizableSeparator withHandle />

				<ResizablePanel id='results' minSize={100}>
					<TableDisplay
						data={previewOutput.data as Record<string, unknown>[]}
						columns={previewOutput.columns}
						className='h-full'
						tableContainerClassName='flex-1 rounded-none border-0'
						emptyLabel='No rows returned'
						maxRowsBeforePagination={100}
					/>
				</ResizablePanel>
			</ResizablePanelGroup>
		</div>
	);
};

import { useState } from 'react';
import { useMutation } from '@tanstack/react-query';
import { ArrowUpRight, Code, Copy, Download, Palette, Pencil, Table as TableIcon } from 'lucide-react';
import { ToolCallWrapper } from './tool-call-wrapper';
import { TableFormatEditDialog } from './display-table-edit-dialog';
import { SqlQueryDisplay } from './sql-query-display';
import { SqlResultDisplay } from './sql-result-display';
import type { ToolCallComponentProps } from '.';
import type { ColumnConditionalFormats } from '@nao/shared/conditional-formatting';
import { useOptionalAgentContext } from '@/contexts/agent.provider';
import { useSidePanel } from '@/contexts/side-panel';
