export const StoryChartEmbed = memo(function StoryChartEmbed({
	chart,
	queryData,
	baselineQueryData,
	liveQuery,
	hasActiveFilters = false,
}: {
	chart: ParsedChartBlock;
	queryData?: QueryDataMap | null;
	baselineQueryData?: QueryDataMap | null;
	liveQuery?: LiveQueryConfig;
	hasActiveFilters?: boolean;
}) {
	const noCacheFetch = useLiveQueryData(chart.queryId, liveQuery);

	const resolved = liveQuery
		? (noCacheFetch.data as { data: Record<string, unknown>[]; columns: string[] } | undefined)
		: queryData?.[chart.queryId];
	const baseline = baselineQueryData?.[chart.queryId];
	const resolvedData = resolved?.data;
	const resolvedColumns = resolved?.columns ?? baseline?.columns ?? [];
	const keepsXDomain =
		hasActiveFilters &&
		Boolean(baseline?.data?.length) &&
		!displayChart.isPieChart(chart.chartType as displayChart.ChartType) &&
		chart.chartType !== 'kpi_card';

	const displayData = useMemo(() => {
		if (!keepsXDomain || !baseline?.data) {
			return resolvedData ?? [];
		}
		return alignChartDataToBaselineX(
			baseline.data,
			resolvedData ?? [],
			chart.xAxisKey,
			chart.series.map((series) => series.data_key),
		);
	}, [keepsXDomain, baseline?.data, resolvedData, chart.xAxisKey, chart.series]);

	if (liveQuery && noCacheFetch.isLoading) {
		return <EmbedLoading />;
	}

	if (!resolved && !keepsXDomain) {
		return <EmbedPlaceholder>Chart data unavailable</EmbedPlaceholder>;
	}

	if (displayData.length === 0) {
		return (
			<EmbedPlaceholder>
				{hasActiveFilters ? 'No results match the selected filters' : 'No data to display'}
			</EmbedPlaceholder>
		);
	}

	if (chart.series.length === 0) {
		return <EmbedPlaceholder>No series configured for chart</EmbedPlaceholder>;
	}

	return (
		<StoryChartEmbedShell chart={chart} availableColumns={resolvedColumns}>
			<ChartDisplay
				data={displayData}
				chartType={chart.chartType as displayChart.ChartType}
				xAxisKey={chart.xAxisKey}
				xAxisType={chart.xAxisType === 'number' ? 'number' : 'category'}
				series={chart.series}
				title={chart.title}
				yAxisMin={chart.yAxisMin}
				yAxisMax={chart.yAxisMax}
				showDataLabels={chart.showDataLabels}
				animate
			/>
		</StoryChartEmbedShell>
	);
});

export const StoryTableEmbed = memo(function StoryTableEmbed({
	table,
	queryData,
	liveQuery,
	hasActiveFilters = false,
}: {
	table: ParsedTableBlock;
	queryData?: QueryDataMap | null;
	liveQuery?: LiveQueryConfig;
	hasActiveFilters?: boolean;
}) {
	const noCacheFetch = useLiveQueryData(table.queryId, liveQuery);

	const resolvedResult = liveQuery
		? (noCacheFetch.data as { data: Record<string, unknown>[]; columns: string[] } | undefined)
		: queryData?.[table.queryId];

	if (liveQuery && noCacheFetch.isLoading) {
		return <EmbedLoading />;
	}

	if (!resolvedResult) {
		return <EmbedPlaceholder>Table data unavailable</EmbedPlaceholder>;
	}

	if (!resolvedResult.data || resolvedResult.data.length === 0) {
		return (
			<EmbedPlaceholder>
				{hasActiveFilters ? 'No results match the selected filters' : 'No data to display'}
			</EmbedPlaceholder>
		);
	}

	const columns = resolvedResult.columns ?? [];
	return (
		<DataTableCard
			data={resolvedResult.data}
			columns={columns}
