import { createContext, useContext, type ReactNode } from 'react';
import type { StoryFilterSelections } from '@nao/shared/sql-template';

import type { StoryFilterApi } from '@/hooks/use-story-filters';

export type StoryQuerySqlSource = {
	api: StoryFilterApi;
	selections: StoryFilterSelections;
};

const StoryQuerySqlContext = createContext<StoryQuerySqlSource | null>(null);

export function StoryQuerySqlProvider({
	value,
	children,
}: {
	value: StoryQuerySqlSource | null;
	children: ReactNode;
}) {
	return <StoryQuerySqlContext.Provider value={value}>{children}</StoryQuerySqlContext.Provider>;
}

export function useStoryQuerySql(): StoryQuerySqlSource | null {
	return useContext(StoryQuerySqlContext);
}

import { useQuery } from '@tanstack/react-query';
import { Loader2 } from 'lucide-react';

import { SqlQueryDisplay } from '@/components/tool-calls/sql-query-display';
import type { StoryQuerySqlSource } from '@/contexts/story-query-sql';
import { trpc } from '@/main';

export function StoryChartQueryView({
	queryId,
	source,
}: {
	queryId: string;
	source: StoryQuerySqlSource;
}) {
	const ownedQuery = useQuery({
		...trpc.story.getQuerySql.queryOptions({
			chatId: source.api.kind === 'owned' ? source.api.chatId : '',
			storySlug: source.api.kind === 'owned' ? source.api.storySlug : '',
			queryId,
			selections: source.selections,
		}),
		enabled: source.api.kind === 'owned',
	});

	const sharedQuery = useQuery({
		...trpc.storyShare.getQuerySql.queryOptions({
			shareId: source.api.kind === 'shared' ? source.api.shareId : '',
			queryId,
			selections: source.selections,
		}),
		enabled: source.api.kind === 'shared',
	});

	const query = source.api.kind === 'shared' ? sharedQuery : ownedQuery;
	const data = query.data;

	if (query.isLoading) {
		return (
			<div className='flex items-center gap-2 rounded-lg border border-dashed p-4 text-sm text-muted-foreground'>
				<Loader2 className='size-4 animate-spin' />
				Loading query…
			</div>
		);
	}

	if (query.isError || !data) {
		return (
			<div className='rounded-lg border border-dashed p-4 text-sm text-muted-foreground'>
				{query.error?.message ?? 'Query unavailable'}
			</div>
		);
	}

	const showBoth = data.sqlQuery.trim() !== data.renderedSql.trim();

	return (
		<div className='flex flex-col gap-4 rounded-lg border bg-muted/20 p-3'>
			{showBoth ? (
				<>
					<section className='flex flex-col gap-1'>
						<h4 className='text-xs font-medium uppercase tracking-wide text-muted-foreground'>
							Template query
						</h4>
						<SqlQueryDisplay query={data.sqlQuery} />
					</section>
					<section className='flex flex-col gap-1'>
						<h4 className='text-xs font-medium uppercase tracking-wide text-muted-foreground'>
							Executed query
						</h4>
						<SqlQueryDisplay query={data.renderedSql} />
					</section>
				</>
			) : (
				<section className='flex flex-col gap-1'>
					<h4 className='text-xs font-medium uppercase tracking-wide text-muted-foreground'>Query</h4>
					<SqlQueryDisplay query={data.renderedSql} />
				</section>
			)}
		</div>
	);
}

import { Code, Pencil } from 'lucide-react';
import { memo, useMemo, useState } from 'react';
import type { UIMessage } from '@nao/backend/chat';
import type { displayChart } from '@nao/shared/tools';

import { StoryChartQueryView } from '@/components/side-panel/story-chart-query';
import { ChartDisplay } from '@/components/tool-calls/display-chart';
import { ChartConfigEditDialog } from '@/components/tool-calls/display-chart-edit-dialog';
import { Button } from '@/components/ui/button';
import { useOptionalAgentContext } from '@/contexts/agent.provider';
import { useStoryChartEdit } from '@/contexts/story-chart-edit';
import { useStoryEmbedData } from '@/contexts/story-embed-data';
import { useStoryQuerySql } from '@/contexts/story-query-sql';
import { sortByDateKey } from '@/lib/charts.utils';
import { cn } from '@/lib/utils';

interface ChartBlock {
	queryId: string;
	chartType: string;
	xAxisKey: string;
	xAxisType: string | null;
	series: Array<{ data_key: string; color: string; label?: string; is_total?: boolean }>;
	yAxisMin?: number;
	yAxisMax?: number;
	title: string;
	showDataLabels?: boolean;
	rawTag?: string;
}

export const StoryChartEmbed = memo(function StoryChartEmbed({ chart }: { chart: ChartBlock }) {
	const agent = useOptionalAgentContext();
	const embedData = useStoryEmbedData();

	const sourceData = useMemo(() => {
		const fromEmbedData = embedData?.[chart.queryId];
		if (fromEmbedData) {
			return fromEmbedData;
		}

		const findInMessages = (messages: UIMessage[]) => {
			for (const message of messages) {
				for (const part of message.parts) {
					if (part.type === 'tool-execute_sql' && part.output?.id === chart.queryId) {
						return part.output;
					}
				}
			}
			return null;
		};

		return findInMessages(agent?.messages ?? []);
	}, [embedData, agent?.messages, chart.queryId]);

	const data = useMemo(
		() =>
			sourceData?.data && chart.xAxisType === 'date'
				? sortByDateKey(sourceData.data, chart.xAxisKey)
				: (sourceData?.data ?? []),
		[sourceData?.data, chart.xAxisType, chart.xAxisKey],
	);

	if (!sourceData?.data || sourceData.data.length === 0) {
		return (
			<div className='my-2 rounded-lg border border-dashed p-4 text-center text-sm text-muted-foreground'>
				Chart data unavailable (query: {chart.queryId})
			</div>
		);
	}

	if (chart.series.length === 0) {
		return (
			<div className='my-2 rounded-lg border border-dashed p-4 text-center text-sm text-muted-foreground'>
				No series configured for chart
			</div>
		);
	}

	const xAxisType = chart.xAxisType === 'number' ? 'number' : ('category' as const);

	return (
		<StoryChartEmbedShell chart={chart} availableColumns={sourceData.columns ?? []}>
			<ChartDisplay
				data={data}
				chartType={chart.chartType as displayChart.ChartType}
				xAxisKey={chart.xAxisKey}
				xAxisType={xAxisType}
				series={chart.series}
				title={chart.title}
				yAxisMin={chart.yAxisMin}
				yAxisMax={chart.yAxisMax}
				showDataLabels={chart.showDataLabels}
			/>
		</StoryChartEmbedShell>
	);
});

interface StoryChartEmbedShellProps {
	chart: ChartBlock;
	availableColumns: string[];
	children: React.ReactNode;
}

/**
 * Wraps a rendered chart with an "Edit chart" button when the surrounding story
 * context provides a save handler.
 */
export function StoryChartEmbedShell({ chart, availableColumns, children }: StoryChartEmbedShellProps) {
	const edit = useStoryChartEdit();
	const querySqlSource = useStoryQuerySql();
	const [isEditOpen, setIsEditOpen] = useState(false);
	const [showQuery, setShowQuery] = useState(false);
	const canEdit = Boolean(edit && chart.rawTag);
	const canViewQuery = Boolean(querySqlSource);
	const showHeader = canEdit || canViewQuery || (chart.chartType != 'kpi_card' && chart.title);

	const config = useMemo<displayChart.ChartInput>(
		() => ({
			query_id: chart.queryId,
			chart_type: chart.chartType as displayChart.ChartType,
			x_axis_key: chart.xAxisKey,
			x_axis_type: (chart.xAxisType || null) as displayChart.XAxisType | null,
			series: chart.series.map((s) => ({
				data_key: s.data_key,
				color: s.color || undefined,
				label: s.label,
				is_total: s.is_total,
			})),
			y_axis_min: chart.yAxisMin,
			y_axis_max: chart.yAxisMax,
			title: chart.title,
			show_data_labels: chart.showDataLabels,
		}),
		[chart],
	);

	return (
		<div className='my-2 flex flex-col gap-4'>
			{showHeader && (
				<div className='flex w-full items-center justify-between gap-2'>
					{chart.chartType != 'kpi_card' && chart.title ? (
						<span className='text-sm font-medium text-foreground flex-1 min-w-0 truncate'>
							{chart.title}
						</span>
					) : (
						<div className='flex-1' />
					)}
					<div className='flex shrink-0 items-center gap-1'>
						{canViewQuery && (
							<Button
								variant='ghost-muted'
								size='icon-xs'
								onClick={() => setShowQuery((current) => !current)}
								title={showQuery ? 'Hide SQL query' : 'View SQL query'}
								className={cn(
									'shrink-0 hover:bg-accent hover:rounded-full',
									showQuery && 'bg-accent rounded-full',
								)}
							>
								<Code className='size-3.5' />
							</Button>
						)}
						{canEdit && (
							<Button
								variant='ghost-muted'
								size='icon-xs'
								onClick={() => setIsEditOpen(true)}
								title='Edit chart'
								className='shrink-0 hover:bg-accent hover:rounded-full'
							>
