import type { executeSql } from '@nao/shared/tools';
import type { UIMessage, UIToolPart } from '@nao/backend/chat';

/** Prefer the latest matching execute_sql in the chat (same rule as stories / SQL edit). */
export function findLatestExecuteSqlInMessages(
	messages: UIMessage[],
	queryId: string,
): { input?: executeSql.Input; output: executeSql.Output } | null {
	let latest: { input?: executeSql.Input; output: executeSql.Output } | null = null;
	for (const message of messages) {
		for (const part of message.parts) {
			if (part.type !== 'tool-execute_sql' || part.output?.id !== queryId) {
				continue;
			}
			const toolPart = part as UIToolPart<'execute_sql'>;
			if (!toolPart.output) {
				continue;
			}
			latest = { input: toolPart.input, output: toolPart.output };
		}
	}
	return latest;
}

/** Update only the latest matching execute_sql part for a query id. */
export function applyExecuteSqlResultToMessages(
	messages: UIMessage[],
	queryId: string,
	input: executeSql.Input,
	output: executeSql.Output,
): UIMessage[] {
	let latestMessageIndex = -1;
	let latestPartIndex = -1;

	for (let messageIndex = 0; messageIndex < messages.length; messageIndex++) {
		const message = messages[messageIndex];
		for (let partIndex = 0; partIndex < message.parts.length; partIndex++) {
			const part = message.parts[partIndex];
			if (part.type !== 'tool-execute_sql') {
				continue;
			}
			const toolPart = part as UIToolPart<'execute_sql'>;
			if (toolPart.output?.id === queryId) {
				latestMessageIndex = messageIndex;
				latestPartIndex = partIndex;
			}
		}
	}

	if (latestMessageIndex < 0 || latestPartIndex < 0) {
		return messages;
	}

	return messages.map((message, messageIndex) => {
		if (messageIndex !== latestMessageIndex) {
			return message;
		}
		const parts = message.parts.map((part, partIndex) => {
			if (partIndex !== latestPartIndex) {
				return part;
			}
			return { ...(part as UIToolPart<'execute_sql'>), input, output } as typeof part;
		});
		return { ...message, parts };
	});
}

import { useQuery, type UseQueryOptions, type UseQueryResult } from '@tanstack/react-query';

import type { StoryFilterApi } from '@/hooks/use-story-filters';
import { trpc } from '@/main';

type StoryOwnedQueryKey = ReturnType<typeof trpc.story.getFilteredQueryData.queryOptions>;
type StorySharedQueryKey = ReturnType<typeof trpc.storyShare.getFilteredQueryData.queryOptions>;

/**
 * Runs either the owned or shared story tRPC query based on api.kind,
 * without enabling the unused branch.
 */
export function useStoryOwnedOrSharedQuery<TData>({
	api,
	enabled = true,
	owned,
	shared,
	...options
}: {
	api?: StoryFilterApi | null;
	enabled?: boolean;
	owned: (api: Extract<StoryFilterApi, { kind: 'owned' }>) => StoryOwnedQueryKey | ReturnType<typeof trpc.story.getQuerySql.queryOptions> | ReturnType<typeof trpc.story.getFilterOptions.queryOptions>;
	shared: (api: Extract<StoryFilterApi, { kind: 'shared' }>) => StorySharedQueryKey | ReturnType<typeof trpc.storyShare.getQuerySql.queryOptions> | ReturnType<typeof trpc.storyShare.getFilterOptions.queryOptions>;
} & Omit<UseQueryOptions<TData>, 'queryKey' | 'queryFn' | 'enabled'>): UseQueryResult<TData> {
	const isOwned = api?.kind === 'owned';
	const isShared = api?.kind === 'shared';

	const ownedOptions = isOwned ? owned(api) : null;
	const sharedOptions = isShared ? shared(api) : null;

	const ownedQuery = useQuery({
		...(ownedOptions ?? trpc.story.getFilteredQueryData.queryOptions({ chatId: '', storySlug: '', selections: {} })),
		enabled: Boolean(enabled && isOwned && ownedOptions),
		...options,
	} as UseQueryOptions<TData>);

	const sharedQuery = useQuery({
		...(sharedOptions ??
			trpc.storyShare.getFilteredQueryData.queryOptions({ shareId: '', selections: {} })),
		enabled: Boolean(enabled && isShared && sharedOptions),
		...options,
	} as UseQueryOptions<TData>);

	return (isShared ? sharedQuery : ownedQuery) as UseQueryResult<TData>;
}

